SourceCode.Declaration:
/// <summary>
/// One menu line. LineType MODULE carries Module (an HSMobileOpsModule symbol); MENU carries
/// SubMenuId.
/// </summary>
[DataContractAttribute]
class HSMobileOpsMenuLineRow
{
    str      lineType;
    str      module;
    str      subMenuId;
}

Method.Source:
[DataMemberAttribute('LineType')]
public str parmLineType(str _value = lineType)
{
    lineType = _value;
    return lineType;
}

[DataMemberAttribute('Module')]
public str parmModule(str _value = module)
{
    module = _value;
    return module;
}

[DataMemberAttribute('SubMenuId')]
public str parmSubMenuId(str _value = subMenuId)
{
    subMenuId = _value;
    return subMenuId;
}
